lean.statement:
∀ {κ c r₀ q Δ γ C : ℝ} {d : ℕ}
  {η : ℕ → ℝ},
  1 ≤ κ →
    0 < c →
      c < 1 / 4 →
        0 ≤ r₀ →
          (∀ (n : ℕ), 0 < η n ∧ η n ≤ c) →
            0 < d →
              2 ≤ q →
                0 < Δ →
                  Δ ≤ 1 / 2 →
                    0 < γ →
                      γ ≤ 1 →
                        8 ≤ C →
                          have K := fun r => (1 + r) / (κ⁻¹ + r);
                          have τ := fun r => if 2 ≤ K r then K r else c;
                          have a := fun r h => (h + τ r) / (1 + r);
                          have step := fun r h => r + (a r h)⁻¹;
                          have r := fun t => Nat.rec r₀ (fun j r => step r (η j)) t;
                          have L := q + Real.log (K r₀ * ↑d * q / Δ);
                          have B := γ / (√(↑d * L) + L);
                          have J := ⌈C * Real.log (Real.exp 1 * K r₀ / B)⌉₊;
                          2 ≤ L ∧
                            (0 < B ∧ B ≤ 1) ∧
                              0 < J ∧ 0 < (r J)⁻¹ ∧ (r J)⁻¹ ≤ B ∧ ↑J ≤ (3 * C + C / 2 * Real.log (1 / γ)) * L
